import './Tags.css'

// 태그 주소 규칙은 여기 한 곳에서만 만든다. 카드와 본문이 각자 만들면 갈라진다.
// 여러 태그는 + 로 잇고, 걸린 태그를 모두 가진 글만 남는다.
export const tagsHref = (tags) =>
  tags.length
    ? `#/blog/tags/${tags.map(encodeURIComponent).join('+')}`
    : '#/blog'

export const parseTags = (param) =>
  param ? param.split('+').map(decodeURIComponent).filter(Boolean) : []

const toggled = (active, tag) =>
  active.includes(tag)
    ? active.filter((item) => item !== tag)
    : [...active, tag]

// 읽기만 하는 목록. 기술 스택처럼 누를 수 없는 것에 쓴다.
export const Tags = ({ items, className = '' }) =>
  items && items.length ? (
    <ul className={`tags ${className}`.trim()}>
      {items.map((item) => (
        <li key={item}>{item}</li>
      ))}
    </ul>
  ) : null

// 누를 수 있는 목록. active 에 든 태그는 채워진 상태로 보인다.
// 누르면 active 에서 빠지거나 붙는다.
export const TagLinks = ({ items, active = [], className = '' }) =>
  items && items.length ? (
    <ul className={`tags tags--links ${className}`.trim()}>
      {items.map((item) => (
        <li key={item} className={active.includes(item) ? 'is-active' : undefined}>
          <a href={tagsHref(toggled(active, item))}>{item}</a>
        </li>
      ))}
    </ul>
  ) : null
