import { createContext, useEffect, useMemo, useState } from 'react'
import PropTypes from 'prop-types'

const ThemeContext = createContext()

// 기본은 라이트다. 예전에는 OS 설정을 따라가서, 라이트로 바꿔 두어도
// 새로고침하면 다시 다크로 돌아갔다. 이제 직접 고른 값만 기억한다.
const DEFAULT_THEME = 'light'
const STORAGE_KEY = 'themeName'

const readStoredTheme = () => {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY)
    return stored === 'dark' || stored === 'light' ? stored : DEFAULT_THEME
  } catch (error) {
    // 저장소를 막아 둔 브라우저에서도 화면은 떠야 한다.
    return DEFAULT_THEME
  }
}

const ThemeProvider = ({ children }) => {
  // 첫 렌더는 항상 기본값이다. localStorage 를 렌더 중에 읽으면
  // 서버 렌더 결과와 어긋난다.
  const [themeName, setThemeName] = useState(DEFAULT_THEME)

  useEffect(() => {
    setThemeName(readStoredTheme())
  }, [])

  const value = useMemo(() => {
    const toggleTheme = () => {
      setThemeName((current) => {
        const next = current === 'dark' ? 'light' : 'dark'

        try {
          window.localStorage.setItem(STORAGE_KEY, next)
        } catch (error) {
          // 저장이 안 되어도 이번 화면 전환은 되어야 한다.
        }

        return next
      })
    }

    return [{ themeName, toggleTheme }]
  }, [themeName])

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
}

ThemeProvider.propTypes = {
  children: PropTypes.node.isRequired,
}

export { ThemeProvider, ThemeContext }
