import { about } from '../../portfolio'
import './About.css'

const About = () => {
  const {
    profileName,
    headlineLines,
    greeting,
    name,
    greetingSuffix,
    role,
    image,
    description,
    resume,
    social,
  } = about

  return (
    <div className='about'>
      <div className='about__media'>
        {image && (
          <img
            className='about__image'
            src={image}
            alt={`${profileName || name} profile`}
          />
        )}
      </div>

      <div className='about__content'>
        {headlineLines && headlineLines.length > 0 && (
          <h1>
            {headlineLines.map(({ before, emphasis, after }) => (
              <span className='about__title-line' key={emphasis}>
                {before}
                <span className='about__name'>{emphasis}</span>
                {after}
              </span>
            ))}
          </h1>
        )}

        {(!headlineLines || headlineLines.length === 0) && name && (
          <h1>
            {greeting} <span className='about__name'>{name}</span>
            {greetingSuffix}
          </h1>
        )}

        {/* 직군 · 이름 · 연락처가 한 줄의 명함이 된다. 흩어 두면 시선이 갈라진다.
            직군과 이름은 굵게, 연락처는 작은 주소 텍스트로 무게를 나눈다. */}
        {role && (
          <div className='about__role-row'>
            <h2 className='about__role'>{role}</h2>

            {social && social.email && (
              <a
                href={`mailto:${social.email}`}
                aria-label='email'
                className='link about__contact-link'
              >
                {social.email}
              </a>
            )}

            {social && social.github && (
              <a
                href={social.github}
                aria-label='github'
                className='link about__contact-link'
              >
                {social.github.replace(/^https?:\/\//, '')}
              </a>
            )}
          </div>
        )}
        {/* 문단이 여러 개면 축이 여러 개다. 한 덩어리로 붙이면 다 같은 말로 읽힌다. */}
        <div className='about__desc'>
          {(Array.isArray(description) ? description : [description])
            .filter(Boolean)
            .map((paragraph) => (
              <p key={paragraph}>{paragraph}</p>
            ))}
        </div>

        {resume && (
          <a href={resume}>
            <span type='button' className='btn btn--outline'>
              Resume
            </span>
          </a>
        )}
      </div>
    </div>
  )
}

export default About
