import { lazy, Suspense, useContext, useEffect, useState } from 'react'
import { ThemeContext } from './contexts/theme'
import { sections } from './portfolio'
import * as content from './generated/projects'
import Header from './components/Header/Header'
import About from './components/About/About'
import EntrySection from './components/Projects/Projects'
import Blog from './components/Blog/Blog'
import { parseTags } from './components/Tags/Tags'
import ScrollToTop from './components/ScrollToTop/ScrollToTop'
import './App.css'

const ProjectDetail = lazy(() =>
  import('./components/ProjectDetail/ProjectDetail')
)

// 주소 한 줄이 화면 하나다. 규칙을 여기 한 곳에 모아 둔다.
// #/resume 이력서 · #/blog 블로그 · #/portfolio 포트폴리오(준비 중).
// 매칭되지 않는 주소(#work 같은 섹션 앵커 포함)는 이력서로 간다.
const ROUTES = [
  { pattern: /^#\/blog\/tags\/([^/?#]+)/, view: 'blog', param: 'tagParam' },
  { pattern: /^#\/blog\/?$/, view: 'blog' },
  { pattern: /^#\/portfolio\/?$/, view: 'portfolio' },
  { pattern: /^#\/resume\/?$/, view: 'resume' },
  { pattern: /^#\/posts\/([^/?#]+)/, view: 'detail', param: 'slug' },
  { pattern: /^#\/projects\/([^/?#]+)/, view: 'detail', param: 'slug' },
]

const routeFromHash = () => {
  const { hash } = window.location

  return (
    ROUTES.map(({ pattern, view, param }) => {
      const match = hash.match(pattern)
      if (!match) return null
      return param
        ? { view, [param]: decodeURIComponent(match[1]) }
        : { view }
    }).find(Boolean) || null
  )
}

const findEntry = (slug) =>
  Object.values(content)
    .flat()
    .find((entry) => entry && entry.slug === slug)

const App = () => {
  const [{ themeName }] = useContext(ThemeContext)
  const [route, setRoute] = useState(routeFromHash)

  useEffect(() => {
    // 맨주소로 들어오면 이력서 주소로 통일한다. 화면은 같지만
    // 주소가 두 개면 공유된 링크가 갈라진다.
    if (!window.location.hash || window.location.hash === '#/') {
      window.location.replace('#/resume')
    }

    const updateRoute = () => {
      setRoute(routeFromHash())
      window.scrollTo(0, 0)
    }

    window.addEventListener('hashchange', updateRoute)
    return () => window.removeEventListener('hashchange', updateRoute)
  }, [])

  return (
    <div id='top' className={`${themeName} app`}>
      <Header />

      <main>
        {route && route.view === 'blog' ? (
          <Blog tags={parseTags(route.tagParam)} />
        ) : null}

        {route && route.view === 'detail' ? (
          <Suspense
            fallback={<div className='project-detail-loading'>Loading…</div>}
          >
            <ProjectDetail project={findEntry(route.slug)} />
          </Suspense>
        ) : null}

        {/* 포트폴리오는 자리부터 잡아 둔다. 주소 체계가 먼저, 내용은 다음. */}
        {route && route.view === 'portfolio' ? (
          <section className='section placeholder-page' aria-label='포트폴리오'>
            <h2 className='section__title'>Portfolio</h2>
            <p className='placeholder-page__body'>
              준비 중입니다. 프로젝트별 상세 기록은{' '}
              <a href='#/resume' className='link'>
                이력서
              </a>
              의 각 항목과{' '}
              <a href='#/blog' className='link'>
                블로그
              </a>
              에서 볼 수 있습니다.
            </p>
          </section>
        ) : null}

        {!route || route.view === 'resume'
          ? sections.map((section, index) => {
              if (section.kind === 'about') return <About key='about' />

              return (
                <EntrySection
                  key={section.id || index}
                  id={section.id}
                  title={section.title}
                  summary={section.summary}
                  grouped={section.grouped}
                  entries={content[section.source]}
                />
              )
            })
          : null}
      </main>

      <ScrollToTop />
    </div>
  )
}

export default App
