import ProjectContainer from '../ProjectContainer/ProjectContainer'
import OrgGroup from '../OrgGroup/OrgGroup'
import { organizations } from '../../portfolio'
import './Projects.css'

// 타입 하나가 렌더러 하나다. 새 타입을 넣을 때 여기만 늘어난다.
// 이력·학력·글 모두 같은 뼈대를 쓴다. 렌더러가 여럿이면 같은 정보가
// 자리마다 다른 모양으로 읽힌다.
const entryRenderers = {
  project: ProjectContainer,
  education: ProjectContainer,
}

// 소속으로 묶인 항목은 소속 칸이 왼쪽을 이미 쓰고 있어 오른쪽 안에만 그린다.
// 묶이지 않은 항목(학력 등)은 자기 이름을 왼쪽 칸에 세워 같은 세로선을 유지한다.
const renderEntry = (entry, standalone) => {
  const EntryRenderer = entryRenderers[entry.type]

  if (!EntryRenderer) {
    throw new Error(`지원하지 않는 콘텐츠 타입: ${entry.type}`)
  }

  return (
    <EntryRenderer key={entry.slug} project={entry} standalone={standalone} />
  )
}

// 소속이 같은 항목을 하나로 묶는다. 순서는 파일 순서를 그대로 따른다.
// 정렬을 다시 하지 않아야 "낮은 번호 = 최근" 규칙이 한 곳에서만 정해진다.
const groupByOrg = (entries) =>
  entries.reduce((groups, entry) => {
    const last = groups[groups.length - 1]

    if (last && last.org === entry.org) {
      last.items.push(entry)
      return groups
    }

    groups.push({ org: entry.org, items: [entry] })
    return groups
  }, [])

const EntrySection = ({ id, title, summary, grouped, entries }) => {
  if (!entries || !entries.length) return null

  return (
    <section id={id} className='section projects'>
      {title ? <h2 className='section__title'>{title}</h2> : null}

      {summary ? <p className='section__summary'>{summary}</p> : null}

      <div className={`projects__list projects__list--${id || 'default'}`}>
        {grouped
          ? groupByOrg(entries).map(({ org, items }) => (
              <OrgGroup key={org || items[0].slug} org={organizations[org]}>
                {items.map((item) => renderEntry(item, false))}
              </OrgGroup>
            ))
          : entries.map((entry) => renderEntry(entry, true))}
      </div>
    </section>
  )
}

export default EntrySection
