import { useEffect, useRef, useState } from 'react'
import { TagLinks } from '../Tags/Tags'
import { posts } from '../../generated/projects'
import './Blog.css'

const hasAll = (post, tags) =>
  tags.every((tag) => (post.tags || []).includes(tag))

// 한 번에 보여 줄 글 수. 스크롤이 바닥 근처에 오면 이만큼씩 더 연다.
// 데이터는 이미 번들에 있으므로 이건 네트워크가 아니라 화면의 문제다 —
// 목록이 길어져도 첫 화면이 벽처럼 느껴지지 않게 한다.
const PAGE_SIZE = 10

const Blog = ({ tags = [] }) => {
  const visible = posts.filter((post) => hasAll(post, tags))
  const [limit, setLimit] = useState(PAGE_SIZE)
  const sentinelRef = useRef(null)

  // 필터가 바뀌면 처음부터 다시 센다.
  const tagKey = tags.join('+')
  useEffect(() => {
    setLimit(PAGE_SIZE)
  }, [tagKey])

  // 바닥 감시 요소가 뷰포트 400px 앞까지 오면 다음 묶음을 연다.
  // 스크롤 이벤트 대신 IntersectionObserver — 스크롤마다 계산하지 않는다.
  useEffect(() => {
    const node = sentinelRef.current
    if (!node) return undefined

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          setLimit((current) => current + PAGE_SIZE)
        }
      },
      { rootMargin: '400px 0px' }
    )

    observer.observe(node)
    return () => observer.disconnect()
  }, [limit, tagKey])

  const shown = visible.slice(0, limit)

  // 고를 수 있는 태그는 남은 글에 실제로 붙어 있는 것만이다.
  // 누르면 결과가 0건이 되는 태그를 남겨 두면 필터가 아니라 미로가 된다.
  const available = [
    ...new Set([...tags, ...visible.flatMap((post) => post.tags || [])]),
  ]

  return (
    <section className='section blog' aria-label='블로그'>
      <div className='blog__hero'>
        <TagLinks items={available} active={tags} className='blog__hero-tags' />

        {tags.length ? (
          <a href='#/blog' className='link blog__clear'>
            필터 해제
          </a>
        ) : null}
      </div>

      {shown.length ? (
        <ul className='blog__list'>
          {shown.map((post) => (
            <li className='blog__card' key={post.slug}>
              <a className='blog__card-link' href={`#/posts/${post.slug}`}>
                <span className='blog__card-head'>
                  <span className='blog__card-title'>{post.name}</span>
                  {post.date ? (
                    <span className='blog__card-date'>{post.date}</span>
                  ) : null}
                </span>
                <span className='blog__card-summary'>{post.subtitle}</span>
              </a>

              <TagLinks
                items={post.tags}
                active={tags}
                className='blog__card-tags'
              />
            </li>
          ))}
        </ul>
      ) : (
        <p className='blog__empty'>이 조건으로 쓴 글이 아직 없습니다.</p>
      )}

      {limit < visible.length ? (
        <div ref={sentinelRef} className='blog__sentinel' aria-hidden='true' />
      ) : null}
    </section>
  )
}

export default Blog
