import './EntryLinks.css'

// 링크는 라벨(Github ↗) 대신 주소 텍스트 그대로 보여 준다.
// 소속 머리글의 jungle.krafton.com 표기와 같은 규칙 — 어디로 가는지
// 주소가 직접 말하게 하고, 같은 정보가 자리마다 다른 옷을 입지 않게 한다.
// 내부(#/) 링크는 보여 줄 주소가 없으므로 라벨을 그대로 쓴다.
const linkText = (href, label) =>
  href.startsWith('#')
    ? label
    : href.replace(/^https?:\/\//, '').replace(/\/$/, '')

// 내부 블로그(#/posts/) 링크는 여기서 그리지 않는다 — 글 링크는 불릿의
// 단어 링크가 이미 맡고 있어서, 링크 줄에 또 있으면 같은 문이 두 개가 된다.
const isExternalRow = ({ href }) => !href.startsWith('#')

// pending 은 자리만 잡아 둔 것이라 눌리지 않고 색만 죽는다.
const EntryLinks = ({ links }) => {
  const rows = (links || []).filter(isExternalRow)

  return rows.length ? (
    <nav className='entry-links'>
      {rows.map(({ label, href, external, pending }) =>
        pending ? (
          <span
            key={label}
            className='entry-links__item entry-links__item--pending'
            title='아직 공개할 것이 없습니다'
          >
            {label}
          </span>
        ) : (
          <a
            key={href}
            href={href}
            className='link entry-links__item'
            target={external ? '_blank' : undefined}
            rel={external ? 'noreferrer' : undefined}
          >
            {linkText(href, label)}
          </a>
        )
      )}
    </nav>
  ) : null
}

export default EntryLinks
