import EntryLinks from '../EntryLinks/EntryLinks'
import { InlineMarkdown } from '../Markdown/Markdown'
import { TagLinks } from '../Tags/Tags'
import './ProjectContainer.css'

// 소속 안에서 만든 것 하나. 소속이 왼쪽 칸을 이미 쓰고 있으므로 여기서는
// 오른쪽 칸 안에서만 위에서 아래로 쌓는다.
// standalone 이면 소속이 없는 항목이라 자기 이름을 왼쪽 칸에 세운다.
const ProjectContainer = ({ project, standalone }) => {
  const head = (
    <div className='project__aside'>
      <h3 className='project__name'>{project.name}</h3>

      {standalone ? null : <EntryLinks links={project.links} />}

      {project.status ? (
        <p className='project__status'>{project.status}</p>
      ) : null}

      {/* 한 줄 요약(팀 규모 · 기여 경계). 소속에 묶인 항목의 기간은 소속
          머리글이 한 번만 말한다 — 항목마다 반복하면 같은 정보가 두 자리에서
          다른 형식으로 읽힌다. 소속이 없는 standalone(학력 등)은 말해 줄
          머리글이 없으므로 여기서 기간을 보여 준다. */}
      {standalone && project.period ? (
        <p className='project__period'>{project.period}</p>
      ) : null}

      {project.subtitle ? (
        <p className='project__meta'>
          <InlineMarkdown>{project.subtitle}</InlineMarkdown>
        </p>
      ) : null}
    </div>
  )

  // 제목과 불릿만 남긴다. 소제목을 지우면 항목 사이 경계가 없어지므로
  // 불릿을 한 줄기로 잇고 기술 태그는 프로젝트 끝에 한 번만 모은다.
  const details = (project.highlights || []).flatMap((item) => item.details)
  const stack = [
    ...new Set([
      ...(project.highlights || []).flatMap((item) => item.stack || []),
      ...(project.stack || []),
    ]),
  ]

  const body = (
    <div className='project__body'>
      {details.length ? (
        <ul className='project__item-details'>
          {details.map((detail) => (
            <li key={detail}>
              <InlineMarkdown>{detail}</InlineMarkdown>
            </li>
          ))}
        </ul>
      ) : null}

      {/* 태그를 누르면 그 태그로 걸러진 블로그 목록으로 간다.
          본문과 블로그가 같은 태그 체계를 쓰므로 여기서 이어 준다. */}
      <TagLinks items={stack} className='project__stack' />
    </div>
  )

  return (
    <article className={`project${standalone ? ' project--standalone' : ''}`}>
      {head}
      {body}
    </article>
  )
}

export default ProjectContainer
