import './OrgGroup.css'

// 소속 한 덩어리. 왼쪽 칸은 "어디서 언제", 오른쪽 칸은 "거기서 만든 것들".
// 회사 이름을 항목마다 반복하지 않고 왼쪽에 한 번만 세워 두면,
// 훑는 사람이 왼쪽을 따라 내려가며 볼 곳을 고를 수 있다.
const OrgGroup = ({ org, children }) => {
  if (!org) return <>{children}</>

  const { name, note, period, summary, link } = org

  return (
    <section className='org'>
      <div className='org__aside'>
        <h3 className='org__name'>{name}</h3>

        {link ? (
          <a className='link org__link' href={link} target='_blank' rel='noreferrer'>
            {link.replace(/^https?:\/\//, '').replace(/\/$/, '')}
          </a>
        ) : null}

        {note ? <p className='org__note'>{note}</p> : null}
        {period ? <p className='org__period'>{period}</p> : null}
      </div>

      <div className='org__body'>
        {summary ? <p className='org__summary'>{summary}</p> : null}
        <div className='org__entries'>{children}</div>
      </div>
    </section>
  )
}

export default OrgGroup
