// react-markdown v6 resolves correctly through its package entry, but the
// legacy resolver bundled with react-scripts 4 reports a false positive.
// eslint-disable-next-line
import ReactMarkdown from 'react-markdown'

// 링크와 문단 규칙은 여기 한 곳에만 둔다. 컴포넌트마다 같은 것을 다시 쓰면
// 한쪽에서 target 이나 rel 을 고칠 때 나머지가 그대로 남는다.
const MarkdownLink = ({ href, children }) => {
  const external = /^https?:\/\//i.test(href || '')

  return (
    <a
      href={href}
      className='link'
      target={external ? '_blank' : undefined}
      rel={external ? 'noreferrer' : undefined}
    >
      {children}
    </a>
  )
}

// 한 줄짜리 값은 문단 태그로 감싸면 위아래 여백이 생겨 줄 간격이 어긋난다.
const Unwrapped = ({ children }) => <>{children}</>

// 유튜브 주소를 이미지 문법(![제목](주소))으로 쓰면 본문에서 바로 재생된다.
// 링크로만 두면 독자가 페이지를 떠나야 한다 — 근거 영상은 글 안에서 재생돼야 한다.
// t= 또는 start= 초는 embed 의 start 로 이어 준다.
const YOUTUBE_ID = /(?:youtube\.com\/(?:embed\/|watch\?v=)|youtu\.be\/)([\w-]{11})/
const START_AT = /[?&](?:t|start)=(\d+)/

const MarkdownImage = ({ src, alt }) => {
  const youtube = YOUTUBE_ID.exec(src || '')

  if (youtube) {
    const start = START_AT.exec(src || '')
    const query = start ? `?start=${start[1]}` : ''

    return (
      <span className='markdown-video'>
        <iframe
          src={`https://www.youtube.com/embed/${youtube[1]}${query}`}
          title={alt || 'YouTube video'}
          loading='lazy'
          allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture'
          allowFullScreen
        />
      </span>
    )
  }

  return <img src={src} alt={alt} loading='lazy' />
}

const inlineComponents = { a: MarkdownLink, p: Unwrapped }
const blockComponents = { a: MarkdownLink, img: MarkdownImage }

// 제목·요약·불릿처럼 한 줄로 들어가는 값
export const InlineMarkdown = ({ children }) => (
  <ReactMarkdown components={inlineComponents}>{children}</ReactMarkdown>
)

// 상세 페이지 본문처럼 문단이 여러 개인 값
export const BlockMarkdown = ({ children }) => (
  <ReactMarkdown components={blockComponents}>{children}</ReactMarkdown>
)
